SELECT customer, SUM(amount) AS total FROM orders GROUP BY customer ORDER BY total DESC;
--
SELECT customer, SUM(amount) AS total FROM orders GROUP BY customer HAVING SUM(amount) > 500;
--
SELECT region, AVG(amount) AS avg_amt FROM orders GROUP BY region HAVING AVG(amount) > 250;
--
SELECT customer, COUNT(*) AS num_orders FROM orders GROUP BY customer HAVING COUNT(*) >= 2;
